            "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"65\" font-size=\"34\" fill=\"#ffd700\" font-weight=\"bold\" text-anchor=\"middle\">Lesson Recap</text><rect x=\"100\" y=\"140\" width=\"900\" height=\"460\" rx=\"18\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"3\"/><text x=\"550\" y=\"190\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"bold\">Mill's Ethical Arc</text><text x=\"550\" y=\"250\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">Greatest Happiness Principle</text><text x=\"550\" y=\"290\" font-size=\"22\" fill=\"#ffd700\" text-anchor=\"middle\">↓</text><text x=\"550\" y=\"330\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">Contrast with Kant's Deontology</text><text x=\"550\" y=\"370\" font-size=\"22\" fill=\"#ffd700\" text-anchor=\"middle\">↓</text><text x=\"550\" y=\"410\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">Higher/Lower Pleasures</text><text x=\"550\" y=\"450\" font-size=\"22\" fill=\"#ffd700\" text-anchor=\"middle\">↓</text><text x=\"550\" y=\"490\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">Proof of Utility and Its Critics</text><text x=\"550\" y=\"540\" font-size=\"22\" fill=\"#ffd700\" text-anchor=\"middle\">↓</text><text x=\"550\" y=\"580\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">Two Genuine Unresolved Tensions</text><rect x=\"150\" y=\"640\" width=\"800\" height=\"360\" rx=\"18\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"3\"/><text x=\"550\" y=\"690\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"bold\">Next: On Liberty</text><text x=\"550\" y=\"740\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">The Harm Principle</text><text x=\"550\" y=\"790\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">Freedom of thought and speech</text><text x=\"550\" y=\"840\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">The tyranny of the majority</text><text x=\"550\" y=\"890\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">Individuality and experiments</text><text x=\"550\" y=\"935\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">in living</text></svg>",
